    opportunity_id,
    type,
    clue_id,
    content,
    follow_time,
    owner,
    contact_id,
    create_time,
    update_time,
    create_user,
    update_user
FROM
    follow_up_record
WHERE
    organization_id =#{orgId}
  and type = #{type}

    AND customer_id = #{request.sourceId}


    AND clue_id = #{request.sourceId}


    AND opportunity_id = #{request.sourceId}


    AND type = #{type}


    AND organization_id = #{orgId}


    AND content like concat('%', #{request.keyword},'%')


    AND follow_time >= #{request.startTime}


    AND follow_time <= #{request.endTime}




ORDER BY follow_time DESC, create_time DESC

