SELECT fur.id, fur.customer_id, fur.opportunity_id, fur.type, fur.clue_id, fur.content, fur.follow_time, fur.owner, fur.contact_id, fur.create_time, fur.update_time, fur.create_user, fur.update_user, fur.follow_method, fur.organization_id, if (fur.type = 'CLUE', c.pool_id, cu.pool_id) as poolId FROM follow_up_record fur LEFT JOIN clue c ON c.id = fur.clue_id LEFT JOIN customer cu ON cu.id = fur.customer_id
join sys_organization_user souu on fur.owner = souu.user_id
WHERE fur.organization_id = #{orgId} and (c.transition_type is null or c.transition_type != 'CUSTOMER')
AND fur.follow_time >= #{request.startTime}
AND fur.follow_time <= #{request.endTime}
AND (
( fur.type = 'CLUE'
AND c.name like concat('%', #{request.keyword},'%')
AND fur.owner = #{userId}
AND ( souu.department_id IN
#{deptId}
OR fur.owner = #{userId}
)
) OR
( fur.type = 'CUSTOMER'
AND cu.name like concat('%', #{request.keyword},'%')
AND fur.owner = #{userId}
AND ( souu.department_id IN
#{deptId}
OR fur.owner = #{userId}
)
) )

