mapper.select:
SELECT cu.id AS customerId, cu.name AS customerName, COUNT(*) AS recordCount, MAX(fur.follow_time) AS latestFollowTime, SUBSTRING_INDEX(GROUP_CONCAT(fur.content ORDER BY fur.follow_time DESC, fur.create_time DESC SEPARATOR '||CORDYS||'), '||CORDYS||', 1) AS latestContent, SUBSTRING_INDEX(GROUP_CONCAT(fur.contact_id ORDER BY fur.follow_time DESC, fur.create_time DESC SEPARATOR '||CORDYS||'), '||CORDYS||', 1) AS contactId, SUBSTRING_INDEX(GROUP_CONCAT(cc.name ORDER BY fur.follow_time DESC, fur.create_time DESC SEPARATOR '||CORDYS||'), '||CORDYS||', 1) AS contactName, SUBSTRING_INDEX(GROUP_CONCAT(cc.phone ORDER BY fur.follow_time DESC, fur.create_time DESC SEPARATOR '||CORDYS||'), '||CORDYS||', 1) AS contactPhone FROM follow_up_record fur INNER JOIN customer cu ON cu.id COLLATE utf8mb4_general_ci = fur.customer_id COLLATE utf8mb4_general_ci AND cu.organization_id COLLATE utf8mb4_general_ci = fur.organization_id COLLATE utf8mb4_general_ci LEFT JOIN customer_contact cc ON cc.id COLLATE utf8mb4_general_ci = fur.contact_id COLLATE utf8mb4_general_ci LEFT JOIN sys_organization_user owner_org ON owner_org.user_id COLLATE utf8mb4_general_ci = fur.owner COLLATE utf8mb4_general_ci AND owner_org.organization_id = #{orgId} WHERE
AND 1 = 0
AND fur.owner = #{request.owner}
AND cu.customer_source = #{request.customerSource}
AND ( cu.name LIKE concat('%', #{request.keyword}, '%') OR fur.content LIKE concat('%', #{request.keyword}, '%') OR cc.name LIKE concat('%', #{request.keyword}, '%') OR cc.phone LIKE concat('%', #{request.keyword}, '%') )
GROUP BY cu.id, cu.name ORDER BY latestFollowTime DESC, recordCount DESC

select
customer_id,
opportunity_id,
clue_id,
follow_time,
owner
from follow_up_record
where organization_id = #{orgId}
and type = #{type}

    AND customer_id = #{customerId}


    AND clue_id = #{clueId}


    AND opportunity_id = #{opportunityId}

order by follow_time desc
limit 1

