SELECT ewe.follow_record_id AS followRecordId, ewa.download_url AS downloadUrl FROM email_webhook_event ewe JOIN email_webhook_attachment ewa ON ewa.event_id = ewe.id WHERE ewe.follow_record_id IN
#{id}
AND ewa.download_url IS NOT NULL AND ewa.download_url != ''

SELECT link.followRecordId AS followRecordId, CASE WHEN media.msg_media_type IN ('1', '2') THEN 'emotion' ELSE media.msg_media_type END AS msgMediaType, media.media_index AS mediaIndex, media.file_name AS fileName, media.mime_type AS mimeType, media.size_bytes AS sizeBytes, media.duration_ms AS durationMs, media.fetch_status AS fetchStatus, media.crm_asset_ref AS crmAssetRef FROM ( SELECT CONVERT(rel.follow_record_id USING utf8mb4) COLLATE utf8mb4_general_ci AS followRecordId, CONVERT(rel.message_id USING utf8mb4) COLLATE utf8mb4_general_ci AS messageId FROM wecom_ingestion_message_follow_record rel WHERE rel.follow_record_id IN
#{id}
UNION SELECT CONVERT(msg.follow_record_id USING utf8mb4) COLLATE utf8mb4_general_ci AS followRecordId, CONVERT(msg.id USING utf8mb4) COLLATE utf8mb4_general_ci AS messageId FROM wecom_ingestion_message msg WHERE msg.follow_record_id IN
#{id}
AND msg.follow_record_id IS NOT NULL AND TRIM(msg.follow_record_id) != '' UNION SELECT CONVERT(fur.id USING utf8mb4) COLLATE utf8mb4_general_ci AS followRecordId, CONVERT(msg.id USING utf8mb4) COLLATE utf8mb4_general_ci AS messageId FROM follow_up_record fur JOIN customer c ON c.id COLLATE utf8mb4_general_ci = fur.customer_id COLLATE utf8mb4_general_ci AND c.organization_id COLLATE utf8mb4_general_ci = fur.organization_id COLLATE utf8mb4_general_ci LEFT JOIN sys_user su ON su.id COLLATE utf8mb4_general_ci = fur.owner COLLATE utf8mb4_general_ci JOIN wecom_ingestion_message msg ON msg.organization_id COLLATE utf8mb4_general_ci = fur.organization_id COLLATE utf8mb4_general_ci WHERE fur.id IN
#{id}
AND LOWER(COALESCE(msg.msg_type, '')) IN ('image', 'video', 'voice', 'file', 'emotion', '1', '2') AND fur.content IS NOT NULL AND fur.content COLLATE utf8mb4_general_ci LIKE CONVERT(CONCAT( '%', '[', DATE_FORMAT(FROM_UNIXTIME(msg.send_time / 1000), '%Y-%m-%d %H:%i:%s'), '] ', CASE WHEN LOWER(COALESCE(msg.message_direction, '')) = 'inbound' THEN CONCAT(COALESCE(c.name, '客户'), '发来') ELSE CONCAT(COALESCE(su.name, '联系专员'), '发出') END, ' ', CASE LOWER(COALESCE(msg.msg_type, '')) WHEN 'text' THEN '文本' WHEN 'image' THEN '图片' WHEN 'voice' THEN '语音' WHEN 'video' THEN '视频' WHEN 'file' THEN '文件' WHEN 'emotion' THEN '表情' WHEN 'redpacket' THEN '红包' WHEN 'voiptext' THEN '语音通话' WHEN 'meeting_voice_call' THEN '语音通话' WHEN 'voice_call' THEN '语音通话' WHEN 'voip_doc_share' THEN '视频通话' WHEN 'meeting_video_call' THEN '视频通话' WHEN 'video_call' THEN '视频通话' ELSE COALESCE(msg.msg_type, '消息') END, CHAR(10), COALESCE(msg.content_text, ''), '%' ) USING utf8mb4) COLLATE utf8mb4_general_ci ) link JOIN wecom_ingestion_message msg ON msg.id COLLATE utf8mb4_general_ci = link.messageId COLLATE utf8mb4_general_ci JOIN wecom_ingestion_media media ON ( media.message_id COLLATE utf8mb4_general_ci = msg.id COLLATE utf8mb4_general_ci OR media.event_id COLLATE utf8mb4_general_ci = msg.id COLLATE utf8mb4_general_ci ) WHERE LOWER(media.msg_media_type) IN ('image', 'video', 'voice', 'file', 'emotion', '1', '2') ORDER BY link.followRecordId, msg.send_time, media.media_index

SELECT link.followRecordId AS followRecordId, msg.send_time AS sendTime, msg.content_text AS contentText, msg.extra_json AS extraJson FROM ( SELECT CONVERT(rel.follow_record_id USING utf8mb4) COLLATE utf8mb4_general_ci AS followRecordId, CONVERT(rel.message_id USING utf8mb4) COLLATE utf8mb4_general_ci AS messageId FROM wecom_ingestion_message_follow_record rel WHERE rel.follow_record_id IN
#{id}
UNION SELECT CONVERT(msg.follow_record_id USING utf8mb4) COLLATE utf8mb4_general_ci AS followRecordId, CONVERT(msg.id USING utf8mb4) COLLATE utf8mb4_general_ci AS messageId FROM wecom_ingestion_message msg WHERE msg.follow_record_id IN
#{id}
AND msg.follow_record_id IS NOT NULL AND TRIM(msg.follow_record_id) != '' UNION SELECT CONVERT(fur.id USING utf8mb4) COLLATE utf8mb4_general_ci AS followRecordId, CONVERT(msg.id USING utf8mb4) COLLATE utf8mb4_general_ci AS messageId FROM follow_up_record fur JOIN customer c ON c.id COLLATE utf8mb4_general_ci = fur.customer_id COLLATE utf8mb4_general_ci AND c.organization_id COLLATE utf8mb4_general_ci = fur.organization_id COLLATE utf8mb4_general_ci LEFT JOIN sys_user su ON su.id COLLATE utf8mb4_general_ci = fur.owner COLLATE utf8mb4_general_ci JOIN wecom_ingestion_message msg ON msg.organization_id COLLATE utf8mb4_general_ci = fur.organization_id COLLATE utf8mb4_general_ci WHERE fur.id IN
#{id}
AND LOWER(COALESCE(msg.msg_type, '')) = 'voiptext' AND fur.content IS NOT NULL AND fur.content COLLATE utf8mb4_general_ci LIKE CONVERT(CONCAT( '%', '[', DATE_FORMAT(FROM_UNIXTIME(msg.send_time / 1000), '%Y-%m-%d %H:%i:%s'), '] ', CASE WHEN LOWER(COALESCE(msg.message_direction, '')) = 'inbound' THEN CONCAT(COALESCE(c.name, '客户'), '发来') ELSE CONCAT(COALESCE(su.name, '联系专员'), '发出') END, ' ', CASE LOWER(COALESCE(msg.msg_type, '')) WHEN 'text' THEN '文本' WHEN 'image' THEN '图片' WHEN 'voice' THEN '语音' WHEN 'video' THEN '视频' WHEN 'file' THEN '文件' WHEN 'emotion' THEN '表情' WHEN 'redpacket' THEN '红包' WHEN 'voiptext' THEN '语音通话' WHEN 'meeting_voice_call' THEN '语音通话' WHEN 'voice_call' THEN '语音通话' WHEN 'voip_doc_share' THEN '视频通话' WHEN 'meeting_video_call' THEN '视频通话' WHEN 'video_call' THEN '视频通话' ELSE COALESCE(msg.msg_type, '消息') END, CHAR(10), COALESCE(msg.content_text, ''), '%' ) USING utf8mb4) COLLATE utf8mb4_general_ci ) link JOIN wecom_ingestion_message msg ON msg.id COLLATE utf8mb4_general_ci = link.messageId COLLATE utf8mb4_general_ci WHERE LOWER(msg.msg_type) = 'voiptext' ORDER BY link.followRecordId, msg.send_time, msg.id
